/* Generated by Trae Work — 周四001-008 赛果复盘图表 */
(function () {
  var ACCENT = '#38bdf8';
  var ACCENT2 = '#fbbf24';
  var GOOD = '#34d399';
  var BAD = '#f87171';
  var MUTED = '#94a3b8';
  var INK = '#f1f5f9';
  var BG2 = '#1e293b';
  var RULE = '#334155';

  function baseGrid() {
    return { left: 40, right: 16, top: 30, bottom: 30, containLabel: true };
  }
  function baseTooltip() {
    return {
      backgroundColor: 'rgba(15,23,42,0.92)',
      borderColor: RULE,
      textStyle: { color: INK, fontSize: 12 },
    };
  }
  function baseAxis() {
    return {
      axisLine: { lineStyle: { color: RULE } },
      axisLabel: { color: MUTED, fontSize: 11 },
      splitLine: { lineStyle: { color: RULE, type: 'dashed' } },
    };
  }

  // ============ 图 1: HAD / HHAD 命中分布 ============
  var matchNames = ['001\n艾卜哈', '002\n克拉约瓦', '003\n帕福斯', '004\n维京古', '005\n利雅得青年', '006\n流浪者', '007\n安德莱赫特', '008\n哈茨'];
  var hadHit = [0, 1, 0, 1, 1, 0, 1, 0];   // HAD 方向命中
  var hhadHit = [1, 0, 1, 0, 1, 0, 1, 0];  // HHAD 让球命中

  var chartHit = echarts.init(document.getElementById('chart-hit'));
  chartHit.setOption({
    tooltip: Object.assign(baseTooltip(), {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      formatter: function (params) {
        var idx = params[0].dataIndex;
        var had = hadHit[idx] ? '命中' : '未中';
        var hhad = hhadHit[idx] ? '命中' : '未中';
        return '<b>' + matchNames[idx].replace('\n', ' ') + '</b><br/>' +
          'HAD 方向: <span style="color:' + (hadHit[idx] ? GOOD : BAD) + '">' + had + '</span><br/>' +
          'HHAD 让球: <span style="color:' + (hhadHit[idx] ? GOOD : BAD) + '">' + hhad + '</span>';
      },
    }),
    legend: {
      data: ['HAD 方向', 'HHAD 让球'],
      textStyle: { color: MUTED },
      top: 0,
    },
    grid: baseGrid(),
    xAxis: Object.assign(baseAxis(), {
      type: 'category',
      data: matchNames,
      axisLabel: { color: MUTED, fontSize: 10, interval: 0 },
    }),
    yAxis: Object.assign(baseAxis(), {
      type: 'value',
      min: 0,
      max: 1,
      interval: 0.5,
      splitLine: { show: false },
      axisLabel: { color: MUTED, fontSize: 11, formatter: function (v) { return v === 1 ? '命中' : '未中'; } },
    }),
    series: [
      {
        name: 'HAD 方向',
        type: 'bar',
        data: hadHit,
        barWidth: 18,
        itemStyle: {
          color: function (p) { return p.value === 1 ? GOOD : BAD; },
          borderRadius: [4, 4, 0, 0],
        },
        label: { show: true, position: 'top', color: INK, fontSize: 11, formatter: function (p) { return p.value === 1 ? '✓' : '✗'; } },
      },
      {
        name: 'HHAD 让球',
        type: 'bar',
        data: hhadHit,
        barWidth: 18,
        itemStyle: {
          color: function (p) { return p.value === 1 ? ACCENT : 'rgba(148,163,184,0.35)'; },
          borderRadius: [4, 4, 0, 0],
        },
        label: { show: true, position: 'top', color: INK, fontSize: 11, formatter: function (p) { return p.value === 1 ? '✓' : '✗'; } },
      },
    ],
  });

  // ============ 图 2: qiumiwu 增强信号分布 ============
  // 每场触发的信号类型 (1=触发) 与判断结果
  var signalTypes = ['排名差', '加权状态分', '伤停量化'];
  var signalMatrix = [
    [1, 0, 0], // 001
    [1, 0, 0], // 002
    [0, 1, 0], // 003
    [1, 0, 0], // 004
    [1, 0, 0], // 005
    [1, 1, 0], // 006
    [0, 1, 0], // 007
    [0, 1, 0], // 008
  ];
  var signalResult = ['错误', '错误', '部分', '正确', '正确', '部分', '正确', '错误'];

  var chartSignal = echarts.init(document.getElementById('chart-signal'));
  chartSignal.setOption({
    tooltip: Object.assign(baseTooltip(), {
      trigger: 'item',
      formatter: function (p) {
        var idx = p.dataIndex;
        var sigName = p.seriesName;
        var res = signalResult[idx];
        var color = res === '正确' ? GOOD : (res === '部分' ? ACCENT2 : BAD);
        return '<b>' + matchNames[idx].replace('\n', ' ') + '</b><br/>' +
          sigName + '<br/>信号判断: <span style="color:' + color + '">' + res + '</span>';
      },
    }),
    legend: {
      data: signalTypes,
      textStyle: { color: MUTED },
      top: 0,
    },
    grid: baseGrid(),
    xAxis: Object.assign(baseAxis(), {
      type: 'category',
      data: matchNames,
      axisLabel: { color: MUTED, fontSize: 10, interval: 0 },
    }),
    yAxis: Object.assign(baseAxis(), {
      type: 'value',
      min: 0,
      max: 1,
      interval: 0.5,
      splitLine: { show: false },
      axisLabel: { color: MUTED, fontSize: 11, formatter: function (v) { return v === 1 ? '触发' : ''; } },
    }),
    series: signalTypes.map(function (name, si) {
      var colors = [ACCENT, ACCENT2, '#a78bfa'];
      return {
        name: name,
        type: 'bar',
        stack: 'signal',
        data: signalMatrix.map(function (row, ri) {
          return {
            value: row[si],
            itemStyle: {
              color: row[si] ? colors[si] : 'transparent',
              borderRadius: row[si] ? [3, 3, 0, 0] : 0,
            },
          };
        }),
        barWidth: 22,
      };
    }),
  });

  // 响应式
  window.addEventListener('resize', function () {
    chartHit.resize();
    chartSignal.resize();
  });
})();
